"""Explain report categories, time of traces, inclusive ranges and addresses."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1841': ('같은 물건의 문제라도 어디로 보내는 중인지, 이미 반납한 물건인지에 따라 붙이는 이름이 달라져요. 오류 이름도 두 가지 정보를 함께 보고 골라요.', '보고 이유 세 가지와 해제 후 사용 표시 두 가지를 조합합니다.', '일반 사용·사용자 복사·USB 전송 세 줄에 해제 표시 없음·있음 두 칸씩 그려 여섯 경우를 적으세요.', ['KMSAN 보고의 reason은 어떤 상황에서 문제를 발견했는지 나타내요. REASON_ANY는 일반적인 사용, REASON_COPY_TO_USER는 사용자 공간으로 복사, REASON_SUBMIT_URB는 USB 전송 요청을 뜻해요. 사용자 공간은 일반 프로그램이 쓰는 영역이에요.', '보고는 origin이라는 원인 기록 번호의 추가 정보에서 UAF 표시를 읽어요. UAF는 use after free의 줄임말로, 반납한 메모리를 다시 사용하는 문제를 뜻해요. is_uaf가 참인지 거짓인지에 따라 같은 reason 안에서도 이름을 달리 골라요.', '일반 사용이면 UAF 표시가 없을 때 uninit-value, 있으면 use-after-free예요. 앞 이름은 아직 준비되지 않은 값의 사용, 뒤 이름은 해제 후 사용을 나타내요. 이 분류는 기록에 있는 표시를 이용하는 것이며 실제 데이터를 다시 읽어 해제 여부를 새로 판정하는 코드는 아니에요.', '사용자 공간으로 복사하는 이유라면 표시가 없을 때 kernel-infoleak, 있으면 kernel-infoleak-after-free예요. infoleak은 정보가 새어 나간다는 뜻이에요. 커널 내부의 준비되지 않은 내용이 외부 프로그램으로 전달되는 문제를 구별해요.', 'USB 전송 이유라면 표시가 없을 때 kernel-usb-infoleak, 있으면 kernel-usb-infoleak-after-free예요. USB 장치 쪽으로 내용이 전달되는 경계라는 점을 이름에 담아요. 세 상황마다 두 경우가 있으므로 3×2=6가지예요.', 'switch는 reason으로 큰 갈래를 고르고, 각 갈래의 조건 ? 앞값 : 뒤값은 UAF가 참이면 앞 이름, 거짓이면 뒤 이름을 골라요. 이 코드는 정의된 세 reason을 전제로 해요. 임의의 다른 숫자까지 자동으로 알맞은 이름으로 고쳐 준다고 생각하면 안 돼요.'], [('사용자 공간으로 복사하는 COPY_TO_USER이고 UAF 표시도 있으면 어떤 이름인가요?', ['언제나 uninit-value예요', 'kernel-infoleak-after-free예요'], '정답은 두 번째예요. 사용자 복사 갈래의 정보 유출 이름에 해제 후 사용이라는 after-free가 붙어요. 일반 사용 이름만 고르면 복사 방향과 UAF 표시를 놓쳐요.'), ('USB 전송 SUBMIT_URB이고 UAF 표시가 없으면 어떤 이름인가요?', ['kernel-usb-infoleak예요', '언제나 use-after-free예요'], '정답은 첫 번째예요. USB 갈래를 고른 뒤 해제 표시가 없는 쪽 이름을 써요. 해제 표시가 없는데 해제 후 사용 이름을 고르는 것은 조건과 맞지 않아요.')]), 'os1842': ('문제가 지금 발견된 곳과 처음 시작된 곳은 다를 수 있어요. 현재 위치와 과거 이동 기록을 따로 보면 원인을 찾기 쉬워져요.', '현재 호출 경로와 과거 생성·저장 기록을 구별합니다.', 'A에서 값 생성→B에서 다른 곳에 저장→C에서 문제 발견을 그리세요. 현재 경로는 C 쪽, 원인 기록은 A·B 쪽으로 나누어 적으세요.', ['stack trace는 함수가 다른 함수를 불러 현재 위치에 이르기까지의 호출 경로예요. frame은 경로 안의 항목 하나예요. 보고에는 지금 문제를 발견한 경로와, 값이 과거에 만들어지거나 저장된 경로가 함께 나올 수 있어요.', 'kmsan_report는 stack_trace_save로 현재 호출 경로를 수집해요. KMSAN_STACK_DEPTH가 배열에 받을 최대 항목 수이고, 마지막 인자 1은 처음 생략할 항목 수를 지정해요. 이 원문에서 최대치는 64지만 언제나 64개를 채운다는 뜻은 아니에요.', '그다음 get_stack_skipnr로 앞쪽 검사 도구 내부 이름을 추가로 몇 개 생략할지 구해요. 최초 skip 인자 1과 나중에 이름을 보고 계산하는 skipnr은 서로 다른 단계예요.', '남은 첫 항목을 BUG 줄의 위치로 사용하고 현재 호출 경로를 출력해요. 직접 첫 항목을 읽는 코드이므로 관심 있는 유효한 항목이 남는다는 호출 경로의 전제도 필요해요. 빈 목록이어도 무조건 첫 항목이 있다고 생각하면 안 돼요.', '이어 kmsan_print_origin(origin)으로 이전에 보관한 원인 기록을 읽어요. origin은 보관소에서 과거 기록을 찾는 번호예요. 현재 경로를 다시 저장한 사본이라고 생각하면 생성과 저장 시점을 구별하기 어려워져요.', '예를 들어 A에서 준비되지 않은 값이 생기고 B에서 복사되어 C에서 쓰였다면 현재 경로는 C의 사용을, 원인 기록은 A의 생성과 남아 있는 B의 저장 경로를 설명할 수 있어요. 저장 한계로 과거 과정이 전부 기록되지 않았을 수도 있어요.'], [('BUG 줄의 현재 경로와 origin의 원인 경로는 항상 같은 시점의 같은 기록인가요?', ['네. 같은 기록을 반드시 두 번 출력해요', '아니요. 현재 사용 위치와 과거 생성·저장 원인을 구별해요'], '정답은 두 번째예요. 현재 경로는 지금 수집하고 origin은 보관한 과거 기록을 조회해요. 이름이 일부 겹치더라도 역할과 수집 시점이 같다는 뜻은 아니에요.'), ('report가 stack_trace_save에 넘기는 처음 skip 값은 얼마인가요?', ['1이에요', '무조건 0이에요'], '정답은 첫 번째예요. 호출문의 마지막 인자가 1이에요. 이후 내부 함수 이름을 보고 추가 생략 수를 계산하므로 두 단계를 따로 따라가세요.')]), 'os1843': ('4번부터 7번까지 칸을 손가락으로 짚으면 4, 5, 6, 7의 네 칸이에요. 끝 칸도 포함하는 범위는 뺄셈 뒤에 1을 더해요.', '보고의 포함 끝 번호와 단일·여러 바이트 출력을 이해합니다.', '0부터 9까지 열 칸을 그리고 4·5·6·7을 색칠하세요. 7-4+1=4를 적으세요.', ['메모리 범위를 바이트 단위로 검사할 때 각 바이트의 위치 번호를 offset이라고 불러요. 시작에서 얼마나 떨어졌는지 뜻해요. 첫 바이트는 0번이며 off_first와 off_last는 문제 구간의 첫 번호와 마지막 번호예요.', '이 보고에서 마지막 번호는 문제 구간에 포함돼요. 앞의 검사 코드는 정상 바이트를 만나면 그 직전 번호를 끝으로 전달해요. 그래서 4부터 7까지는 4, 5, 6, 7의 네 바이트예요.', '포함하는 양끝 번호가 있을 때 개수는 마지막 - 처음 + 1이에요. 7 - 4만 계산하면 두 번호 사이의 간격 3이 나오고, 첫 칸을 포함해 세려면 1을 더해야 해요. 끝 바로 다음 위치를 사용하는 다른 범위 표기와 구별하세요.', 'size는 보고 대상 접근 범위의 크기예요. size가 0이 아니면 바이트 상세를 출력하는 블록에 들어가요. off_first와 off_last가 같으면 Byte라는 단수 표기로 한 위치를, 다르면 Bytes first-last 형태로 범위를 출력해요.', '크기 10의 접근에서 문제 위치가 4부터 7까지라면 Bytes 4-7 of 10이라는 식이에요. 10바이트 전부가 문제라는 뜻이 아니라 전체 10바이트 중 해당 네 바이트의 보고예요. 두 위치가 모두 4이면 Byte 4 of 10처럼 한 칸을 나타내요.', 'size가 0이면 이 바이트 상세 블록을 건너뛰어요. 위치와 길이를 제공하지 않는 경고 경로가 이런 형태를 사용할 수 있어요. 해당 블록을 생략한다는 것이 앞뒤의 보고까지 전부 없어진다는 뜻은 아니에요.'], [('마지막 번호도 포함하는 4번부터 7번까지는 몇 바이트인가요?', ['7-4이므로 3바이트예요', '4, 5, 6, 7이므로 4바이트예요'], '정답은 두 번째예요. 양끝을 포함하므로 7 - 4 + 1 = 4예요. 세 칸 간격과 실제 네 칸 개수를 구별하세요.'), ('size가 0이면 Byte 또는 Bytes로 시작하는 상세 블록을 출력하나요?', ['아니요. 그 if 블록은 건너뛰어요', '네. 언제나 Byte 0을 출력해요'], '정답은 첫 번째예요. if (size)는 0일 때 거짓이에요. 바이트 상세를 건너뛰며, 보고의 다른 출력 조건은 각각 따로 확인해요.')]), 'os1844': ('택배의 출발 주소와 받는 주소는 서로 다른 정보예요. 오류 보고에도 살펴본 메모리의 시작 주소와 복사 목적지 주소가 따로 있어요.', '두 주소의 역할과 각각의 출력 조건을 구별합니다.', '출발 메모리 1000→사용자 목적지 9000이라는 가상 화살표를 그리고 address와 user_addr를 붙이세요.', ['address는 보고 대상 메모리 접근이 시작하는 주소예요. 주소는 메모리에서 위치를 찾는 값이에요. if (address)는 주소가 NULL, 즉 주소 없음 표시가 아닌 경우에 접근 크기와 시작 주소를 출력해요.', 'user_addr는 사용자 공간의 목적지 주소를 담는 인자예요. 사용자 공간은 일반 프로그램이 쓰는 영역이에요. 사용자 복사 경로에서는 커널에서 읽은 출발 위치와 프로그램 쪽으로 복사한 도착 위치가 각각 보고에 필요할 수 있어요.', '사용자 목적지 줄의 조건은 user_addr가 있고 reason이 REASON_COPY_TO_USER여야 한다는 것이에요. &&는 두 조건 모두 참이어야 한다는 뜻이에요. 주소가 있다는 사실 하나만으로는 이 줄을 출력하지 않아요.', '주소가 있어도 reason이 일반 사용인 REASON_ANY면 사용자 목적지 줄은 생략해요. 반대로 이유가 사용자 복사라도 user_addr가 NULL이면 생략해요. 두 조건이 모두 맞을 때만 목적지를 출력해요.', '가상 예에서 출발 주소가 1000, 사용자 목적지가 9000이면 address는 1000이고 user_addr는 9000이에요. 보고된 문제의 offset이 4라면 실제 문제 바이트는 출발에서 4칸 뒤일 수 있지만 시작 주소 줄은 여전히 접근 시작을 설명해요.', '이 두 주소 출력 조건은 size의 바이트 상세 조건과 별도예요. 주소 줄이 출력됐다는 사실만으로 그 주소가 안전하거나 복사가 성공했다고 검사한 것은 아니에요. 이 부분은 받은 정보를 조건에 맞춰 설명하는 출력 코드예요.'], [('user_addr가 있어도 reason이 일반 사용이면 사용자 목적지 줄이 나오나요?', ['네. 주소만 있으면 무조건 나와요', '아니요. COPY_TO_USER라는 이유도 필요해요'], '정답은 두 번째예요. &&로 연결한 두 조건 중 이유 조건이 거짓이에요. 주소 존재와 복사 상황을 함께 확인해야 해요.'), ('address 줄과 user_addr 줄은 항상 같은 위치를 뜻하나요?', ['아니요. 접근 시작 위치와 사용자 목적지를 구별해요', '네. 두 줄은 언제나 같은 주소의 다른 이름이에요'], '정답은 첫 번째예요. 사용자 복사의 출발 메모리와 도착 메모리는 다른 역할이에요. 가상 예의 1000과 9000처럼 각각 따라가면 왜 두 정보가 필요한지 알 수 있어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_456.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
